-- Application-owned schema only. No managed auth/storage schema changes.
create schema if not exists pms_private;
revoke all on schema pms_private from public, anon, authenticated;
alter default privileges in schema public revoke all on tables from anon, authenticated;
alter default privileges in schema public revoke execute on functions from public;

create table public.organizations (
 id uuid primary key default gen_random_uuid(), name text not null check(length(name) between 1 and 160),
 slug text unique, default_currency char(3) not null default 'MXN', default_timezone text not null default 'America/Mexico_City',
 status text not null default 'active' check(status in ('active','suspended')), created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table public.roles (id uuid primary key default gen_random_uuid(),organization_id uuid references public.organizations(id),key text not null,name text not null,is_system boolean not null default false, unique nulls not distinct(organization_id,key));
create table public.permissions (key text primary key,description text not null);
create table public.role_permissions (role_id uuid not null references public.roles(id),permission_key text not null references public.permissions(key),primary key(role_id,permission_key));
create table public.organization_members (organization_id uuid not null references public.organizations(id),user_id uuid not null references auth.users(id),role_id uuid not null references public.roles(id),status text not null default 'active' check(status in ('active','suspended')),all_properties boolean not null default true,invited_by uuid references auth.users(id),joined_at timestamptz not null default now(),primary key(organization_id,user_id));
create table public.properties (
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),name text not null,concept text not null check(concept in ('entire_home','hotel','boutique_hotel','villas','apartments','aparthotel','hostel','bed_and_breakfast','inn','cabins','glamping','resort','camping','multi_unit_complex','other')),
 timezone text not null default 'America/Mexico_City',currency char(3) not null default 'MXN',country_code char(2) not null default 'MX',city text not null default '',address text not null default '',status text not null default 'active',onboarding_state jsonb not null default '{}',version bigint not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,id)
);
create table public.member_property_scopes (organization_id uuid not null,user_id uuid not null,property_id uuid not null,primary key(organization_id,user_id,property_id),foreign key(organization_id,user_id) references public.organization_members(organization_id,user_id),foreign key(organization_id,property_id) references public.properties(organization_id,id));
create table public.property_settings (property_id uuid primary key,organization_id uuid not null,check_in_from time not null default '15:00',check_out_until time not null default '11:00',locale text not null default 'es-MX',allowed_overbooking integer not null default 0 check(allowed_overbooking between 0 and 10),tax_bps integer not null default 0 check(tax_bps between 0 and 10000),policy text not null default '',settings_json jsonb not null default '{}',foreign key(organization_id,property_id) references public.properties(organization_id,id));
create table public.onboarding_drafts (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),user_id uuid not null references auth.users(id),step integer not null default 0,data jsonb not null default '{}',updated_at timestamptz not null default now(),unique(organization_id,user_id));
create table public.amenities(id uuid primary key default gen_random_uuid(),key text not null unique,category text not null,label_i18n jsonb not null);
