create table public.property_amenities(organization_id uuid not null,property_id uuid not null,amenity_id uuid not null references public.amenities(id),metadata jsonb not null default '{}',primary key(property_id,amenity_id),foreign key(organization_id,property_id) references public.properties(organization_id,id));
create table public.inventory_types(id uuid primary key default gen_random_uuid(),organization_id uuid not null,property_id uuid not null,name text not null,code text,sell_mode text not null check(sell_mode in ('unit','bed')),max_occupancy integer not null check(max_occupancy between 1 and 100),base_rate_minor bigint not null check(base_rate_minor between 0 and 100000000000),active boolean not null default true,sort_order integer not null default 0,foreign key(organization_id,property_id) references public.properties(organization_id,id),unique(organization_id,property_id,id),unique(property_id,code));
create table public.units(id uuid primary key default gen_random_uuid(),organization_id uuid not null,property_id uuid not null,inventory_type_id uuid not null,name text not null,parent_unit_id uuid,active boolean not null default true,housekeeping_status text not null default 'clean' check(housekeeping_status in ('clean','dirty','inspected')),version bigint not null default 1,foreign key(organization_id,property_id,inventory_type_id) references public.inventory_types(organization_id,property_id,id),unique(organization_id,property_id,id),foreign key(organization_id,property_id,parent_unit_id) references public.units(organization_id,property_id,id),check(parent_unit_id is null or parent_unit_id<>id),unique(property_id,name));
create table public.unit_attributes(unit_id uuid not null references public.units(id),key text not null,value_json jsonb not null,primary key(unit_id,key));
create table public.inventory_relations(organization_id uuid not null,property_id uuid not null,parent_unit_id uuid not null,child_unit_id uuid not null,relation_type text not null default 'exclusive',quantity integer not null default 1 check(quantity>0),primary key(parent_unit_id,child_unit_id),foreign key(organization_id,property_id,parent_unit_id) references public.units(organization_id,property_id,id),foreign key(organization_id,property_id,child_unit_id) references public.units(organization_id,property_id,id),check(parent_unit_id<>child_unit_id));
create table public.rate_plans(id uuid primary key default gen_random_uuid(),organization_id uuid not null,property_id uuid not null,name text not null,parent_rate_plan_id uuid,active boolean not null default true,foreign key(organization_id,property_id) references public.properties(organization_id,id),unique(organization_id,property_id,id),foreign key(organization_id,property_id,parent_rate_plan_id) references public.rate_plans(organization_id,property_id,id));
create table public.rate_day(id uuid primary key default gen_random_uuid(),organization_id uuid not null,property_id uuid not null,rate_plan_id uuid not null,inventory_type_id uuid not null,stay_date date not null,occupancy_key text not null default 'base',amount_minor bigint not null check(amount_minor between 0 and 100000000000),currency char(3) not null,min_stay integer not null default 1 check(min_stay>0),max_stay integer not null default 730,closed boolean not null default false,cta boolean not null default false,ctd boolean not null default false,version bigint not null default 1,check(max_stay>=min_stay),foreign key(organization_id,property_id,rate_plan_id) references public.rate_plans(organization_id,property_id,id),foreign key(organization_id,property_id,inventory_type_id) references public.inventory_types(organization_id,property_id,id),unique(rate_plan_id,inventory_type_id,stay_date,occupancy_key));
create table public.guests(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),first_name text not null,last_name text not null,email text,phone_e164 text check(phone_e164 is null or phone_e164 ~ '^\+[1-9][0-9]{6,14}$'),country_code char(2),notes text not null default '',pii_classification text not null default 'PII',version bigint not null default 1,created_by uuid references auth.users(id),unique(organization_id,id));
create table public.reservations(id uuid primary key default gen_random_uuid(),organization_id uuid not null,property_id uuid not null,guest_id uuid not null,confirmation_code text not null,arrival_date date not null,departure_date date not null,adults integer not null check(adults>0),children integer not null default 0 check(children>=0),status text not null check(status in ('draft','pending','confirmed','checked_in','checked_out','cancelled','no_show')),source text not null default 'direct',currency char(3) not null,total_minor bigint not null check(total_minor between 0 and 9007199254740991),version bigint not null default 1,booked_at timestamptz not null default now(),cancelled_at timestamptz,notes text not null default '',foreign key(organization_id,property_id) references public.properties(organization_id,id),foreign key(organization_id,guest_id) references public.guests(organization_id,id),check(departure_date>arrival_date and departure_date-arrival_date<=730),unique(property_id,confirmation_code),unique(organization_id,property_id,id));
create table public.reservation_units(id uuid primary key default gen_random_uuid(),organization_id uuid not null,property_id uuid not null,reservation_id uuid not null,inventory_type_id uuid not null,unit_id uuid,rate_plan_id uuid not null,arrival_date date not null,departure_date date not null,guests_count integer not null check(guests_count>0),foreign key(organization_id,property_id,reservation_id) references public.reservations(organization_id,property_id,id),foreign key(organization_id,property_id,inventory_type_id) references public.inventory_types(organization_id,property_id,id),foreign key(organization_id,property_id,unit_id) references public.units(organization_id,property_id,id),foreign key(organization_id,property_id,rate_plan_id) references public.rate_plans(organization_id,property_id,id),check(departure_date>arrival_date));
create table public.reservation_guests(organization_id uuid not null,property_id uuid not null,reservation_id uuid not null,guest_id uuid not null,is_primary boolean not null default false,primary key(reservation_id,guest_id),foreign key(organization_id,property_id,reservation_id) references public.reservations(organization_id,property_id,id),foreign key(organization_id,guest_id) references public.guests(organization_id,id));
create table public.reservation_notes(id uuid primary key default gen_random_uuid(),organization_id uuid not null,property_id uuid not null,reservation_id uuid not null,author_user_id uuid not null references auth.users(id),body text not null,visibility text not null default 'internal',created_at timestamptz not null default now(),foreign key(organization_id,property_id,reservation_id) references public.reservations(organization_id,property_id,id));
create table public.inventory_day(organization_id uuid not null,property_id uuid not null,inventory_type_id uuid not null,stay_date date not null,physical_capacity integer not null check(physical_capacity>=0),held integer not null default 0 check(held>=0),sold integer not null default 0 check(sold>=0),out_of_service integer not null default 0 check(out_of_service>=0),adjustment integer not null default 0,sellable integer generated always as (physical_capacity-held-sold-out_of_service+adjustment) stored,version bigint not null default 1,primary key(property_id,inventory_type_id,stay_date),foreign key(organization_id,property_id,inventory_type_id) references public.inventory_types(organization_id,property_id,id));
create table public.inventory_blocks(id uuid primary key default gen_random_uuid(),organization_id uuid not null,property_id uuid not null,unit_id uuid not null,start_date date not null,end_date date not null,reason text not null,status text not null default 'active' check(status in ('active','released')),foreign key(organization_id,property_id,unit_id) references public.units(organization_id,property_id,id),check(end_date>start_date));
create table public.folios(id uuid primary key default gen_random_uuid(),organization_id uuid not null,property_id uuid not null,reservation_id uuid not null,status text not null default 'open' check(status in ('open','closed')),currency char(3) not null,opened_at timestamptz not null default now(),closed_at timestamptz,foreign key(organization_id,property_id,reservation_id) references public.reservations(organization_id,property_id,id),unique(organization_id,property_id,id),unique(reservation_id));
create table public.folio_items(id uuid primary key default gen_random_uuid(),organization_id uuid not null,property_id uuid not null,folio_id uuid not null,type text not null,description text not null,quantity numeric(12,3) not null default 1 check(quantity>0),unit_amount_minor bigint not null,tax_minor bigint not null default 0,total_minor bigint not null,service_date date not null,created_at timestamptz not null default now(),foreign key(organization_id,property_id,folio_id) references public.folios(organization_id,property_id,id));
create table public.payments(id uuid primary key default gen_random_uuid(),organization_id uuid not null,property_id uuid not null,reservation_id uuid not null,provider text not null,provider_payment_id text not null,amount_minor bigint not null check(amount_minor>0),currency char(3) not null,status text not null check(status in ('pending','succeeded','failed')),method_type text not null default 'tokenized',received_at timestamptz not null default now(),foreign key(organization_id,property_id,reservation_id) references public.reservations(organization_id,property_id,id),unique(organization_id,property_id,id),unique(organization_id,provider,provider_payment_id));
create table public.tasks(id uuid primary key default gen_random_uuid(),organization_id uuid not null,property_id uuid not null,unit_id uuid,kind text not null check(kind in ('housekeeping','maintenance')),title text not null,status text not null default 'pending' check(status in ('pending','in_progress','completed')),priority text not null default 'normal',assignee_id uuid,version bigint not null default 1,foreign key(organization_id,property_id) references public.properties(organization_id,id),foreign key(organization_id,property_id,unit_id) references public.units(organization_id,property_id,id),foreign key(organization_id,assignee_id) references public.organization_members(organization_id,user_id));
create table public.channel_connections(id uuid primary key default gen_random_uuid(),organization_id uuid not null,property_id uuid not null,provider text not null,name text not null,status text not null default 'disconnected',sync_mode text not null default 'ari',field_ownership text not null default 'pms',last_sync timestamptz,last_error_code text,version bigint not null default 1,foreign key(organization_id,property_id) references public.properties(organization_id,id),unique(organization_id,property_id,id));
create table public.channel_mappings(id uuid primary key default gen_random_uuid(),organization_id uuid not null,property_id uuid not null,connection_id uuid not null,inventory_type_id uuid not null,rate_plan_id uuid not null,external_id text not null,foreign key(organization_id,property_id,connection_id) references public.channel_connections(organization_id,property_id,id),foreign key(organization_id,property_id,inventory_type_id) references public.inventory_types(organization_id,property_id,id),foreign key(organization_id,property_id,rate_plan_id) references public.rate_plans(organization_id,property_id,id),unique(connection_id,inventory_type_id,rate_plan_id),unique(connection_id,external_id));
create table public.jobs(id uuid primary key default gen_random_uuid(),organization_id uuid not null,property_id uuid not null,actor_id uuid not null references auth.users(id),type text not null,status text not null default 'queued' check(status in ('queued','running','review','retry','completed','dead_letter')),step integer not null default 0,progress integer not null default 0 check(progress between 0 and 100),payload jsonb not null default '{}',attempts integer not null default 0,max_attempts integer not null default 3,run_after timestamptz not null default now(),locked_until timestamptz,lock_token uuid,last_error_code text,result jsonb not null default '[]',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(organization_id,property_id) references public.properties(organization_id,id),unique(organization_id,property_id,id));
create table public.migration_records(id uuid primary key default gen_random_uuid(),organization_id uuid not null,property_id uuid not null,job_id uuid not null,provider text not null,external_id text not null,external_updated_at timestamptz,fingerprint text not null,canonical_type text not null,canonical_payload jsonb not null,status text not null,error_code text,foreign key(organization_id,property_id,job_id) references public.jobs(organization_id,property_id,id),unique(job_id,canonical_type,external_id));
create table public.migration_conflicts(id uuid primary key default gen_random_uuid(),organization_id uuid not null,property_id uuid not null,job_id uuid not null,record_id uuid not null references public.migration_records(id),code text not null,resolution text,foreign key(organization_id,property_id,job_id) references public.jobs(organization_id,property_id,id));
create table public.external_identities(organization_id uuid not null references public.organizations(id),connection_id text not null,provider text not null,external_type text not null,external_id text not null,internal_id uuid not null,primary key(organization_id,connection_id,provider,external_type,external_id));
create table public.webhook_receipts(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),provider text not null,connection_id text not null,provider_event_id text not null,fingerprint text not null,received_at timestamptz not null default now(),status text not null default 'queued',unique(organization_id,provider,connection_id,provider_event_id));
create table public.raw_provider_events(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),receipt_id uuid not null references public.webhook_receipts(id),redacted_payload jsonb not null,expires_at timestamptz not null);
create table public.outbox_events(id uuid primary key default gen_random_uuid(),organization_id uuid not null,property_id uuid not null,type text not null,entity_id uuid not null,payload jsonb not null default '{}',created_at timestamptz not null default now(),processed_at timestamptz,foreign key(organization_id,property_id) references public.properties(organization_id,id));
create table public.idempotency_keys(organization_id uuid not null references public.organizations(id),actor_id uuid not null references auth.users(id),key text not null check(length(key) between 8 and 120),fingerprint text not null,response jsonb,created_at timestamptz not null default now(),primary key(organization_id,actor_id,key));
create table public.audit_logs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),property_id uuid,actor_type text not null default 'user',actor_id uuid,action text not null,entity_type text not null,entity_id uuid not null,before_json jsonb,after_json jsonb,request_id text not null,created_at timestamptz not null default now(),foreign key(organization_id,property_id) references public.properties(organization_id,id));
create table public.automation_rules(id uuid primary key default gen_random_uuid(),organization_id uuid not null,property_id uuid not null,name text not null,trigger text not null,action text not null check(action in ('create_task','notify_team')),enabled boolean not null default true,foreign key(organization_id,property_id) references public.properties(organization_id,id));
create table public.automation_runs(id uuid primary key default gen_random_uuid(),organization_id uuid not null,property_id uuid not null,rule_id uuid not null references public.automation_rules(id),event_id uuid not null references public.outbox_events(id),status text not null,created_at timestamptz not null default now(),foreign key(organization_id,property_id) references public.properties(organization_id,id),unique(rule_id,event_id));

create index reservation_property_dates on public.reservations(property_id,arrival_date,departure_date) where status in ('pending','confirmed','checked_in','checked_out');
create index reservation_guest on public.reservations(organization_id,guest_id);
create index reservation_unit_dates on public.reservation_units(unit_id,arrival_date,departure_date);
create index members_user on public.organization_members(user_id,organization_id) where status='active';
create index units_type on public.units(inventory_type_id) where active;
create index units_parent on public.units(parent_unit_id) where parent_unit_id is not null;
create index blocks_unit_dates on public.inventory_blocks(unit_id,start_date,end_date) where status='active';
create index jobs_claim on public.jobs(run_after,locked_until) where status in ('queued','retry','running');
create index outbox_pending on public.outbox_events(created_at) where processed_at is null;
create index audit_org_date on public.audit_logs(organization_id,created_at desc);
create index tasks_property_status on public.tasks(property_id,status);

insert into public.permissions(key,description) select key,key from unnest(array['property.read','property.write','reservation.read','reservation.write','reservation.cancel','guest.pii.read','inventory.write','rates.write','finance.read','finance.write','channel.manage','migration.manage','team.manage','audit.read','operations.write','automation.write','report.read']) key;
insert into public.roles(key,name,is_system) select key,key,true from unnest(array['owner','admin','manager','front_desk','housekeeping','finance','viewer']) key;
insert into public.role_permissions select r.id,p.key from public.roles r cross join public.permissions p where r.key in ('owner','admin') or r.key='manager' and p.key<>'team.manage' or r.key='front_desk' and p.key in ('property.read','reservation.read','reservation.write','reservation.cancel','guest.pii.read','finance.read','finance.write','operations.write') or r.key='housekeeping' and p.key in ('property.read','operations.write') or r.key='finance' and p.key in ('property.read','reservation.read','guest.pii.read','finance.read','finance.write','report.read') or r.key='viewer' and p.key in ('property.read','reservation.read','report.read');

create function pms_private.can_access(org uuid,perm text,prop uuid default null) returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.organization_members m join public.organizations o on o.id=m.organization_id join public.roles r on r.id=m.role_id join public.role_permissions rp on rp.role_id=r.id where m.user_id=auth.uid() and m.organization_id=org and m.status='active' and o.status='active' and (r.organization_id is null or r.organization_id=org) and rp.permission_key=perm and (prop is null or exists(select 1 from public.properties p where p.id=prop and p.organization_id=org) and (m.all_properties or exists(select 1 from public.member_property_scopes ps where ps.organization_id=org and ps.user_id=m.user_id and ps.property_id=prop))));
$$;
create function pms_private.can_guest(org uuid,guest uuid) returns boolean language sql stable security definer set search_path='' as $$
 select pms_private.can_access(org,'guest.pii.read') and exists(select 1 from public.organization_members m where m.organization_id=org and m.user_id=auth.uid() and (m.all_properties or exists(select 1 from public.reservations r where r.organization_id=org and r.guest_id=guest and pms_private.can_access(org,'guest.pii.read',r.property_id)) or exists(select 1 from public.guests g where g.id=guest and g.created_by=auth.uid())));
$$;
grant usage on schema pms_private to authenticated;
grant execute on function pms_private.can_access(uuid,text,uuid),pms_private.can_guest(uuid,uuid) to authenticated;

-- Read policies. Direct DML is denied; critical writes go through reviewed RPC only.
do $$ declare tab text;perm text; begin
 for tab,perm in select * from (values('properties','property.read'),('property_settings','property.read'),('property_amenities','property.read'),('inventory_types','property.read'),('units','property.read'),('inventory_relations','property.read'),('rate_plans','property.read'),('rate_day','property.read'),('reservations','reservation.read'),('reservation_units','reservation.read'),('reservation_guests','guest.pii.read'),('reservation_notes','guest.pii.read'),('inventory_day','property.read'),('inventory_blocks','property.read'),('folios','finance.read'),('folio_items','finance.read'),('payments','finance.read'),('tasks','property.read'),('channel_connections','channel.manage'),('channel_mappings','channel.manage'),('migration_records','migration.manage'),('migration_conflicts','migration.manage'),('outbox_events','audit.read'),('audit_logs','audit.read'),('automation_rules','automation.write'),('automation_runs','automation.write')) rules(t,p) loop
  execute format('alter table public.%I enable row level security',tab);
  execute format('revoke all on public.%I from public,anon,authenticated',tab);
  execute format('grant select on public.%I to authenticated',tab);
  execute format('create policy tenant_read on public.%I for select to authenticated using(pms_private.can_access(organization_id,%L,%s))',tab,perm,case when tab='properties' then 'id' else 'property_id' end);
 end loop;
 for tab in select unnest(array['organizations','roles','permissions','role_permissions','organization_members','member_property_scopes','onboarding_drafts','amenities','unit_attributes','guests','jobs','external_identities','webhook_receipts','raw_provider_events','idempotency_keys']) loop
  execute format('alter table public.%I enable row level security',tab);
  execute format('revoke all on public.%I from public,anon,authenticated',tab);
 end loop;
end $$;
grant select on public.organizations,public.roles,public.permissions,public.role_permissions,public.organization_members,public.member_property_scopes,public.onboarding_drafts,public.amenities,public.unit_attributes,public.guests,public.jobs to authenticated;
create policy organizations_read on public.organizations for select to authenticated using(pms_private.can_access(id,'property.read'));
create policy members_read on public.organization_members for select to authenticated using(user_id=auth.uid() and pms_private.can_access(organization_id,'property.read') or pms_private.can_access(organization_id,'team.manage'));
create policy scopes_read on public.member_property_scopes for select to authenticated using(user_id=auth.uid() and pms_private.can_access(organization_id,'property.read') or pms_private.can_access(organization_id,'team.manage'));
create policy roles_read on public.roles for select to authenticated using(organization_id is null or pms_private.can_access(organization_id,'team.manage'));
create policy permissions_read on public.permissions for select to authenticated using(auth.uid() is not null);
create policy role_permissions_read on public.role_permissions for select to authenticated using(exists(select 1 from public.roles r where r.id=role_id));
create policy amenities_read on public.amenities for select to authenticated using(auth.uid() is not null);
create policy attributes_read on public.unit_attributes for select to authenticated using(exists(select 1 from public.units u where u.id=unit_id));
create policy guests_read on public.guests for select to authenticated using(pms_private.can_guest(organization_id,id));
create policy drafts_read on public.onboarding_drafts for select to authenticated using(user_id=auth.uid() and pms_private.can_access(organization_id,'property.write'));
create policy jobs_read on public.jobs for select to authenticated using(pms_private.can_access(organization_id,case type when 'migration' then 'migration.manage' when 'channel_sync' then 'channel.manage' when 'report' then 'report.read' when 'payment' then 'finance.write' else 'automation.write' end,property_id));

create function pms_private.require_access(org uuid,perm text,prop uuid default null) returns void language plpgsql security definer set search_path='' as $$ begin if not pms_private.can_access(org,perm,prop) then raise exception 'FORBIDDEN' using errcode='42501';end if; end $$;
create function pms_private.require_step_up() returns void language plpgsql security definer set search_path='' as $$ begin if coalesce(auth.jwt()->>'aal','')<>'aal2' then raise exception 'STEP_UP_REQUIRED' using errcode='42501';end if;end $$;
create function pms_private.audit(org uuid,prop uuid,action text,entity uuid,request_key text,detail jsonb default '{}') returns void language sql security definer set search_path='' as $$ insert into public.audit_logs(organization_id,property_id,actor_id,action,entity_type,entity_id,request_id,after_json) values(org,prop,auth.uid(),action,split_part(action,'.',1),entity,request_key,detail); $$;
create function pms_private.idempotency_start(org uuid,key text,command jsonb) returns jsonb language plpgsql security definer set search_path='' as $$ declare existing public.idempotency_keys; begin
 if length(key)<8 or length(key)>120 then raise exception 'IDEMPOTENCY_REQUIRED';end if;
 insert into public.idempotency_keys(organization_id,actor_id,key,fingerprint) values(org,auth.uid(),key,md5(command::text)) on conflict do nothing;
 select * into existing from public.idempotency_keys k where k.organization_id=org and k.actor_id=auth.uid() and k.key=idempotency_start.key for update;
 if existing.fingerprint<>md5(command::text) then raise exception 'IDEMPOTENCY_CONFLICT';end if;return existing.response;
end $$;
create function pms_private.idempotency_finish(org uuid,key text,response jsonb) returns jsonb language plpgsql security definer set search_path='' as $$ begin update public.idempotency_keys k set response=idempotency_finish.response where k.organization_id=org and k.actor_id=auth.uid() and k.key=idempotency_finish.key;return response;end $$;
revoke execute on all functions in schema pms_private from public;
